import {button,icon,esc,phraseText,quotedText} from './ui.js';
import {lessonNumberWithVideo} from './video-lesson-state.js';
import {scenarioProgress,scenarioTitle,scenarioLearnsFirst} from './scenario-state.js';
export function renderReplyRepair(s,top,l,c){
 const sceneImage=c.image?`<img class="scenario-image" src="${esc(c.image)}" alt="" width="960" height="480" decoding="async">`:'';
 const p=scenarioProgress(s),x=c.items[p.index],jp=s.courseDirection==='ja-ko',ui=jp?'ja':'ko',lang=jp?'ko':'ja',label=(ko,ja)=>jp?ja:ko;
 const ratio=p.phase==='intro'?0:Math.round((p.index*(scenarioLearnsFirst(l.id)?2:1)+(scenarioLearnsFirst(l.id)?1:0)+(p.checked?1:0))/(l.count*(scenarioLearnsFirst(l.id)?2:1))*100),header=top(`${lessonNumberWithVideo(s,l.number[s.courseDirection])}. ${scenarioTitle(s,l)}`);
 const progress=`<div class="lesson-progress" role="progressbar" aria-label="${label('학습 진행률','学習の進み具合')}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${ratio}"><span style="width:${ratio}%"></span></div>`;
 if(p.phase==='intro')return `${header}${progress}<main class="page scenario-page lesson-top ${c.image?'scenario-illustrated':''}" lang="${ui}">${sceneImage}<h1>${esc(scenarioTitle(s,l))}</h1><p>${quotedText(c.scene)}</p>${button(scenarioLearnsFirst(l.id)?label('학습 시작하기','学習を始める'):label('답장 고치기','返事を直す'),'scenario-next')}</main>`;
 const line=(text,parts,part,meaning)=>`<div class="audio-text-row"><p lang="${lang}">${c.orderRepair&&lang==='ko'?esc(text):phraseText(text,parts||undefined)}</p>${button(icon('sound'),'scenario-audio','icon-button',`data-id="${part}" aria-label="${label('다시 듣기','もう一度聞く')}"`)}</div><details class="message-meaning"><summary>${label('뜻 보기','意味を見る')}</summary><p>${quotedText(meaning)}</p></details>`;
 const options=x.others.map((text,i)=>({text,feedback:x.othersFeedback[i]}));options.splice(l.answers?.[p.index]??p.index,0,{text:x.answer,parts:x.answerParts});
 return `${header}${progress}<main class="page scenario-page repair-page ${c.orderRepair?'order-repair-page':''} ${c.image?'scenario-illustrated':''}" lang="${ui}">${sceneImage}<p class="repair-context">${quotedText(x.context)}</p><section class="repair-original"><h2>${c.orderRepair?label('직원의 확인','店員の確認'):label('처음 쓴 답장','最初の返事')}</h2>${line(x.text,x.phrases,'prompt',x.meaning)}</section>${p.checked?`<section class="repair-result" role="status"><h2>${c.orderRepair?label('바로잡는 말','言い直す表現'):label('고친 답장','言い換えた返事')}</h2>${line(x.answer,x.answerParts,'answer',x.answerMeaning)}<h3>${c.orderRepair?label('바로잡은 부분','確認したポイント'):label('달라진 뜻','変わったニュアンス')}</h3><p class="scenario-feedback">${x.change?`${quotedText(x.change)}<br>`:''}${quotedText(x.hint)}</p></section>`:`<h2 class="repair-task">${quotedText(x.prompt)}</h2><div class="scenario-choices">${options.map((o,i)=>button(c.orderRepair&&lang==='ko'?esc(o.text):phraseText(o.text,o.parts||undefined),'scenario-select',`secondary${p.selected===i?' selected':''}`,`data-id="${i}" lang="${lang}" aria-pressed="${p.selected===i}"${c.orderRepair?` data-choice-audio="choice:${i===(l.answers?.[p.index]??p.index)?0:i<(l.answers?.[p.index]??p.index)?i+1:i}"`:''}`)).join('')}</div>${c.orderRepair?`<details class="chat-choice-meanings"><summary>${label('선택지 뜻 보기','選択肢の意味')}</summary><ol>${options.map(o=>`<li>${quotedText(o.text===x.answer?x.answerMeaning:x.otherMeanings[x.others.indexOf(o.text)])}</li>`).join('')}</ol></details>`:''}${p.retry?`<aside class="scenario-feedback lesson-verdict" role="status"><p>${c.orderRepair?label('이 말은 이런 뜻이에요.','この表現はこういう意味です。'):label('이 답장은 이런 뜻이에요.','この返事はこういう意味です。')}</p><p>${quotedText(options[p.selected]?.feedback||'')}</p></aside>`:''}`}<div class="button-pair">${button(scenarioLearnsFirst(l.id)?label('다시 배우기','もう一度学ぶ'):label('이전','戻る'),'scenario-previous','secondary')}${p.checked?button(p.index===l.count-1?label('학습 마치기','学習を終える'):label('다음','次へ'),'scenario-next'):button(label('확인','確認'),'scenario-check','primary',p.selected===null?'disabled':'')}</div></main>`;
}
